  `comment_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预约备注或评价内容',
  `cancel_time` datetime(0) NULL DEFAULT NULL COMMENT '取消时间',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `fk_appt_user`(`user_id`) USING BTREE,
  INDEX `fk_appt_tech`(`technician_id`) USING BTREE,
  INDEX `fk_appt_item`(`service_item_id`) USING BTREE,
  CONSTRAINT `fk_appt_item` FOREIGN KEY (`service_item_id`) REFERENCES `service_item` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
