  `pay_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付单号',
  `pay_time` datetime(0) NULL DEFAULT NULL COMMENT '支付时间',
