DROP TABLE IF EXISTS `user_wallet`;
CREATE TABLE `user_wallet`  (
  `user_id` bigint(0) NOT NULL COMMENT '用户ID，主键',
  `balance` decimal(10, 2) NOT NULL COMMENT '钱包余额',
  `total_recharge` decimal(10, 2) NOT NULL COMMENT '累计充值金额',
  `total_gift` decimal(10, 2) NOT NULL COMMENT '累计赠送金额',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `updated_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic COMMENT = '用户钱包表';

