-- ----------------------------
-- Table structure for wallet_txn
-- ----------------------------
DROP TABLE IF EXISTS `wallet_txn`;
CREATE TABLE `wallet_txn`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '钱包流水ID',
  `txn_no` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流水号',
  `user_id` bigint(0) NOT NULL COMMENT '用户ID',
  `txn_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流水类型',
  `amount` decimal(10, 2) NOT NULL COMMENT '变动金额',
  `balance_after` decimal(10, 2) NOT NULL COMMENT '变动后余额',
  `related_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联业务类型',
  `related_id` bigint(0) NULL DEFAULT NULL COMMENT '关联业务ID',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `created_at` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `txn_no`(`txn_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic COMMENT = '钱包流水表';

