INSERT INTO `ai_consult_message` VALUES (109, 30, 5, 'USER', '我想\n美白', '', NULL, '2026-05-05 13:10:31');
INSERT INTO `ai_consult_message` VALUES (110, 30, 5, 'ASSISTANT', '您想美白肌肤吗？我为您推荐一些适合的美容美发服务和产品。', '', NULL, '2026-05-05 13:10:31');
INSERT INTO `ai_consult_message` VALUES (111, 30, 5, 'USER', '商品呢', '', NULL, '2026-05-05 13:10:52');
INSERT INTO `ai_consult_message` VALUES (112, 30, 5, 'ASSISTANT', '好的，我明白了！为了美白肌肤，以下是我为您推荐的护肤品：\n\n1. 玻尿酸保湿面膜 - 这款面膜富含玻尿酸成分，能够深层滋润肌肤，帮助美白。\n2. 舒缓修护精华 - 含有丰富的修复成分，可以有效改善肌肤状态，达到美白的效果。\n3. 烟酰胺亮肤精华 - 烟酰胺是一种非常有效的美白成分，可以帮助提亮肤色。\n\n以上产品都是针对美白肌肤的需求精心挑选的，希望对您有所帮助。如果您还有其他需求或者想要了解更多产品信息，欢迎随时向我提问。', '', NULL, '2026-05-05 13:11:02');
