INSERT INTO `ai_consult_message` VALUES (116, 30, 5, 'ASSISTANT', '为了美白肌肤，我为您推荐以下日常护理产品：\n\n1. 玻尿酸保湿面膜 - 69元\n   * 含量丰富的玻尿酸成分，能够深度滋润肌肤。\n\n2. 舒缓修护精华 - 199元\n   * 富含修复因子，帮助肌肤恢复活力。\n\n3. 多肽紧致眼霜 - 189元\n   * 含有多肽成分，有助于改善眼部细纹。\n\n请根据您的具体需求选择合适的产品。', '', NULL, '2026-05-05 13:24:07');
INSERT INTO `ai_consult_message` VALUES (117, 30, 5, 'USER', '预算有限服务和商品怎么搭配', '', NULL, '2026-05-05 13:24:14');
INSERT INTO `ai_consult_message` VALUES (118, 30, 5, 'ASSISTANT', '为了在预算内实现美白肌肤的目标，我为您推荐以下搭配方案：\n\n服务推荐：\n- 补水清洁护理（服务项ID: 1），价格为199元。\n- 肩颈放松理疗（服务项ID: 3），价格为159元。\n- 头皮净澈护理（服务项ID: 12），价格为169元。\n\n商品推荐：\n- 玻尿酸保湿面膜（商品ID: 1），价格为69元。\n- 多肽紧致眼霜（商品ID: 18），价格为189元。\n- 舒缓晒后凝胶（商品ID: 23），价格为69元。', '', NULL, '2026-05-05 13:24:25');
INSERT INTO `ai_consult_record` VALUES (6, 5, NULL, NULL, '/uploads/ai-consult/c87799fb-667b-40e9-8c30-fe051619046d.png', '请根据上传照片推荐适合的发型方向和系统内服务项目。', '结合照片与文字诉求，推荐优先从修饰脸部比例、提升发型层次感和改善发质状态三个方向入手。', '已结合上传照片进行演示级形象分析，建议将脸型、发量与日常通勤风格一起考虑。', '[{\"name\":\"锁骨层次发\",\"reason\":\"适合大多数日常场景，能兼顾修饰脸型与整体轻盈感。\",\"maintenanceLevel\":\"MEDIUM\",\"fitScore\":92},{\"name\":\"自然侧分中长发\",\"reason\":\"线条简洁、适配度高，适合通勤与日常维护。\",\"maintenanceLevel\":\"LOW\",\"fitScore\":88},{\"name\":\"低层次内扣短中发\",\"reason\":\"打理成本更低，适合追求稳定、整洁效果。\",\"maintenanceLevel\":\"LOW\",\"fitScore\":84}]', '[{\"serviceItemId\":3,\"serviceName\":\"肩颈放松理疗\",\"categoryName\":\"美体塑形\",\"durationMin\":45,\"price\":159.00,\"reason\":\"肩颈放松理疗更利于把 AI 的发型建议落到实际造型与到店沟通中。\",\"fitScore\":72},{\"serviceItemId\":1,\"serviceName\":\"补水清洁护理\",\"categoryName\":\"面部护理\",\"durationMin\":60,\"price\":199.00,\"reason\":\"补水清洁护理更利于把 AI 的发型建议落到实际造型与到店沟通中。\",\"fitScore\":72},{\"serviceItemId\":2,\"serviceName\":\"深层修护护理\",\"categoryName\":\"面部护理\",\"durationMin\":90,\"price\":299.00,\"reason\":\"深层修护护理更利于把 AI 的发型建议落到实际造型与到店沟通中。\",\"fitScore\":72}]', NULL, '[\"建议先从低风险、易维护的造型方案开始尝试。\",\"若准备预约护理项目，优先选择与当前发质困扰直接相关的项目。\",\"AI 结果可作为到店沟通参考，但最终仍建议由现场发型师综合判断。\"]', NULL, NULL, NULL, NULL, '当前为本地演示推荐结果。配置外部多模态 API 后，可启用真实 AI 图像分析。', 'LOCAL_DEMO', 'mock', '2026-04-21 12:27:10', '2026-04-21 12:27:10');
