INSERT INTO `ai_consult_record` VALUES (30, 5, '预算有限服务和商品怎么搭配', 'CARE_PLANNING', '', '我想\n美白', '美白肌肤的日常护理推荐', '本轮主要依据你的文字诉求和门店当前服务、商品目录生成建议。', '[]', '[{\"serviceItemId\":1,\"serviceName\":\"补水清洁护理\",\"categoryName\":\"面部护理\",\"durationMin\":60,\"price\":199.00,\"reason\":\"补水清洁护理可以帮助肌肤保持水分，促进美白效果。\",\"fitScore\":0},{\"serviceItemId\":3,\"serviceName\":\"肩颈放松理疗\",\"categoryName\":\"身体理疗\",\"durationMin\":45,\"price\":159.00,\"reason\":\"肩颈放松理疗可以缓解压力，提升整体状态，间接有利于肌肤的美白。\",\"fitScore\":0},{\"serviceItemId\":12,\"serviceName\":\"头皮净澈护理\",\"categoryName\":\"头皮养护\",\"durationMin\":45,\"price\":169.00,\"reason\":\"头皮净澈护理可以清除头皮污垢，为毛囊提供更好的环境，有助于头发生长和健康，从而间接影响脸部肌肤的美白。\",\"fitScore\":0}]', '[{\"productId\":1,\"productName\":\"玻尿酸保湿面膜\",\"categoryName\":\"护肤产品\",\"price\":69.00,\"stock\":85,\"reason\":\"玻尿酸保湿面膜含有丰富的玻尿酸成分，能够深度滋润肌肤，有助于美白。\",\"fitScore\":0},{\"productId\":18,\"productName\":\"多肽紧致眼霜\",\"categoryName\":\"护肤产品\",\"price\":189.00,\"stock\":85,\"reason\":\"多肽紧致眼霜含有多肽成分，有助于改善眼部细纹，同时也可以作为面部护肤品的一部分进行美白。\",\"fitScore\":0},{\"productId\":23,\"productName\":\"舒缓晒后凝胶\",\"categoryName\":\"护肤产品\",\"price\":69.00,\"stock\":160,\"reason\":\"舒缓晒后凝胶含有多种植物提取物，有助于舒缓肌肤，减少因日晒引起的色素沉着，有助于美白。\",\"fitScore\":0}]', '[\"预约前可以先确认预算、可到店时间和最想改善的一项问题。\",\"商品建议先少量尝试，确认肤质或发质适配后再稳定使用。\"]', '[\"服务推荐\",\"商品推荐\"]', '{\"initialRequest\":\"我想\\n美白\",\"hasImage\":false}', '{\"stage\":\"CARE_PLANNING\",\"summaryText\":\"美白肌肤的日常护理推荐\",\"faceHairObservation\":\"本轮主要依据你的文字诉求和门店当前服务、商品目录生成建议。\",\"styleDirections\":[],\"careTips\":[\"预约前可以先确认预算、可到店时间和最想改善的一项问题。\",\"商品建议先少量尝试，确认肤质或发质适配后再稳定使用。\"],\"serviceRecommendations\":[{\"serviceItemId\":1,\"serviceName\":\"补水清洁护理\",\"categoryName\":\"面部护理\",\"durationMin\":60,\"price\":199.00,\"reason\":\"补水清洁护理可以帮助肌肤保持水分，促进美白效果。\",\"fitScore\":0},{\"serviceItemId\":3,\"serviceName\":\"肩颈放松理疗\",\"categoryName\":\"身体理疗\",\"durationMin\":45,\"price\":159.00,\"reason\":\"肩颈放松理疗可以缓解压力，提升整体状态，间接有利于肌肤的美白。\",\"fitScore\":0},{\"serviceItemId\":12,\"serviceName\":\"头皮净澈护理\",\"categoryName\":\"头皮养护\",\"durationMin\":45,\"price\":169.00,\"reason\":\"头皮净澈护理可以清除头皮污垢，为毛囊提供更好的环境，有助于头发生长和健康，从而间接影响脸部肌肤的美白。\",\"fitScore\":0}],\"productRecommendations\":[{\"productId\":1,\"productName\":\"玻尿酸保湿面膜\",\"categoryName\":\"护肤产品\",\"price\":69.00,\"stock\":85,\"reason\":\"玻尿酸保湿面膜含有丰富的玻尿酸成分，能够深度滋润肌肤，有助于美白。\",\"fitScore\":0},{\"productId\":18,\"productName\":\"多肽紧致眼霜\",\"categoryName\":\"护肤产品\",\"price\":189.00,\"stock\":85,\"reason\":\"多肽紧致眼霜含有多肽成分，有助于改善眼部细纹，同时也可以作为面部护肤品的一部分进行美白。\",\"fitScore\":0},{\"productId\":23,\"productName\":\"舒缓晒后凝胶\",\"categoryName\":\"护肤产品\",\"price\":69.00,\"stock\":160,\"reason\":\"舒缓晒后凝胶含有多种植物提取物，有助于舒缓肌肤，减少因日晒引起的色素沉着，有助于美白。\",\"fitScore\":0}],\"nextQuestions\":[\"预算有限的话先做哪一步？\",\"服务和商品怎么搭配更稳妥？\",\"到店前需要注意什么？\"],\"intentTags\":[\"服务推荐\",\"商品推荐\"],\"disclaimer\":\"AI 顾问建议仅供参考，实际服务方案和商品使用请结合到店沟通、个人肤质发质与过敏情况综合判断。\",\"analysisMode\":\"REMOTE_API\"}', '2026-05-05 13:24:26', 'AI 顾问建议仅供参考，实际服务方案和商品使用请结合到店沟通、个人肤质发质与过敏情况综合判断。', 'REMOTE_API', '{\"choices\":[{\"finish_reason\":\"stop\",\"index\":0,\"message\":{\"content\":\"{\\\"assistantMessage\\\":\\\"为了在预算内实现美白肌肤的目标，我为您推荐以下搭配方案：\\\\n\\\\n服务推荐：\\\\n- 补水清洁护理（服务项ID: 1），价格为199元。\\\\n- 肩颈放松理疗（服务项ID: 3），价格为159元。\\\\n- 头皮净澈护理（服务项ID: 12），价格为169元。\\\\n\\\\n商品推荐：\\\\n- 玻尿酸保湿面膜（商品ID: 1），价格为69元。\\\\n- 多肽紧致眼霜（商品ID: 18），价格为189元。\\\\n- 舒缓晒后凝胶（商品ID: 23），价格为69元。\\\",\\\"stage\\\":\\\"SERVICE_PLANNING\\\",\\\"summaryText\\\":\\\"美白肌肤的日常护理推荐\\\",\\\"faceSummary\\\":\\\"\\\",\\\"hairStyles\\\":[],\\\"serviceRecommendations\\\":[{\\\"serviceItemId\\\":1,\\\"reason\\\":\\\"补水清洁护理可以帮助肌肤保持水分，促进美白效果。\\\",\\\"fitScore\\\":0},{\\\"serviceItemId\\\":3,\\\"reason\\\":\\\"肩颈放松理疗可以缓解压力，提升整体状态，间接有利于肌肤的美白。\\\",\\\"fitScore\\\":0},{\\\"serviceItemId\\\":12,\\\"reason\\\":\\\"头皮净澈护理可以清除头皮污垢，为毛囊提供更好的环境，有助于头发生长和健康，从而间接影响脸部肌肤的美白。\\\",\\\"fitScore\\\":0}],\\\"productRecommendations\\\":[{\\\"productId\\\":1,\\\"reason\\\":\\\"玻尿酸保湿面膜含有丰富的玻尿酸成分，能够深度滋润肌肤，有助于美白。\\\",\\\"fitScore\\\":0},{\\\"productId\\\":18,\\\"reason\\\":\\\"多肽紧致眼霜含有多肽成分，有助于改善眼部细纹，同时也可以作为面部护肤品的一部分进行美白。\\\",\\\"fitScore\\\":0},{\\\"productId\\\":23,\\\"reason\\\":\\\"舒缓晒后凝胶含有多种植物提取物，有助于舒缓肌肤，减少因日晒引起的色素沉着，有助于美白。\\\",\\\"fitScore\\\":0}],\\\"careTips\\\":[\\\"定期使用美白面膜，每周一到两次，可以有效促进肌肤美白。\\\",\\\"保持良好的作息时间，避免熬夜，有助于肌肤的自我修复和美白。\\\",\\\"多吃富含维生素C的水果和蔬菜，如橙子、草莓、番茄等，有助于增强肌肤抗氧化能力，促进美白。\\\"],\\\"nextQuestions\\\":[\\\"您希望在哪一天进行这些护理？\\\",\\\"您是否有特定的预算限制？\\\",\\\"您对哪种类型的护理更感兴趣？\\\"],\\\"intentTags\\\":[\\\"美白肌肤\\\",\\\"预算有限\\\"],\\\"disclaimer\\\":\\\"以上建议仅供参考，最终以到店沟通为准。\\\"}\",\"role\":\"assistant\"}}],\"created\":1777958664,\"id\":\"2026050513241422084e298d0f4b1d\",\"model\":\"glm-4v-flash\",\"request_id\":\"2026050513241422084e298d0f4b1d\",\"usage\":{\"completion_tokens\":618,\"prompt_tokens\":4862,\"total_tokens\":5480}}', '2026-05-05 13:10:31', '2026-05-05 13:10:31');
INSERT INTO `announcement` VALUES (1, '系统试运行公告', 'BFSM 已进入试运行阶段，预约与商城两条业务线均可体验。', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=1200&q=80', 'BFSM 系统已进入试运行阶段，欢迎体验预约服务、商品下单、钱包充值与站内消息等核心流程。', 'PUBLISHED', '2026-04-14 22:03:56', '2026-04-14 11:28:08', '2026-04-14 22:03:56');
INSERT INTO `announcement` VALUES (2, '活动通知', '新用户首单服务享受 9 折优惠，商城精选商品同步参加活动。', 'https://images.unsplash.com/photo-1515377905703-c4788e51af15?auto=format&fit=crop&w=1200&q=80', '本月新用户首次预约服务可享受 9 折优惠，部分护肤商品也同步参与限时活动，详情可在首页资讯区查看。', 'PUBLISHED', '2026-04-14 22:03:56', '2026-04-14 11:28:08', '2026-04-14 22:03:56');
INSERT INTO `announcement` VALUES (3, '系统功能升级说明', '技师请假、上下班打卡和站内通知能力已接入。', 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?auto=format&fit=crop&w=1200&q=80', '当前版本已补齐技师请假审批、上下班打卡、排班联动与站内通知，首页同步接入轮播图和新闻资讯模块。', 'PUBLISHED', '2026-04-14 22:03:56', '2026-04-14 22:03:56', '2026-04-14 22:03:56');
