INSERT INTO `service_item` VALUES (20, 2, '深睡肩颈舒压', '围绕肩颈与头部压力点进行舒缓护理，适合睡眠浅、精神紧绷的人群。', 'https://images.unsplash.com/photo-1515377905703-c4788e51af15?auto=format&fit=crop&w=900&q=80', 75, 269.00, 'ON');
INSERT INTO `service_item` VALUES (21, 2, '热石背部放松', '结合温热能量与背部舒缓手法，帮助释放背部僵硬和疲惫感。', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?auto=format&fit=crop&w=900&q=80', 80, 299.00, 'ON');
INSERT INTO `service_item` VALUES (22, 2, '足腿循环舒缓', '针对小腿酸胀和久站疲劳进行放松护理，让身体重新轻盈起来。', 'https://images.unsplash.com/photo-1519823551278-64ac92734fb1?auto=format&fit=crop&w=900&q=80', 60, 199.00, 'ON');
INSERT INTO `service_item` VALUES (23, 2, '芳香睡眠放松', '以温和芳香和舒缓节奏帮助进入放松状态，适合高压和睡前放松。', 'https://images.unsplash.com/photo-1600334089648-b0d9d3028eb2?auto=format&fit=crop&w=900&q=80', 70, 259.00, 'ON');
INSERT INTO `service_item` VALUES (24, 1, '玫瑰润泽护理', '补充肌肤水分并提升柔润感，让面部状态更饱满、细腻。', 'https://images.unsplash.com/photo-1616394584738-fc6e612e71b9?auto=format&fit=crop&w=900&q=80', 70, 259.00, 'ON');
INSERT INTO `service_item` VALUES (25, 1, '胶原弹润护理', '围绕弹润与细腻肤感进行护理，适合干纹明显和肤感粗糙人群。', 'https://images.unsplash.com/photo-1570172619644-dfd03ed5d881?auto=format&fit=crop&w=900&q=80', 90, 399.00, 'ON');
INSERT INTO `service_item` VALUES (26, 1, '清透控油护理', '清理多余油脂并帮助维持清爽状态，适合混油和油性肌肤。', 'https://images.unsplash.com/photo-1556228578-8c89e6adf883?auto=format&fit=crop&w=900&q=80', 60, 229.00, 'ON');
INSERT INTO `service_item` VALUES (27, 1, '晒后舒缓修护', '针对日晒后泛红、干燥和紧绷感进行舒缓护理。', 'https://images.unsplash.com/photo-1598440947619-2c35fc9aa908?auto=format&fit=crop&w=900&q=80', 75, 289.00, 'ON');
INSERT INTO `service_item` VALUES (28, 1, '小气泡净肤护理', '温和清洁毛孔并改善粗糙肤感，适合作为周期性清洁护理。', 'https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?auto=format&fit=crop&w=900&q=80', 50, 189.00, 'ON');
INSERT INTO `service_item` VALUES (29, 4, '头皮深呼吸护理', '帮助头皮恢复清爽舒适，适合头皮闷、痒或压力型紧绷。', 'https://images.unsplash.com/photo-1527799820374-dcf8d9d4a388?auto=format&fit=crop&w=900&q=80', 60, 239.00, 'ON');
INSERT INTO `service_item` VALUES (30, 4, '发根蓬松养护', '改善发根扁塌和油腻观感，让发型更轻盈有空气感。', 'https://images.unsplash.com/photo-1519415943484-9fa1873496d4?auto=format&fit=crop&w=900&q=80', 55, 219.00, 'ON');
INSERT INTO `service_item` VALUES (31, 4, '头皮敏感舒缓', '针对敏感、紧绷、干痒等状态进行温和舒缓护理。', 'https://images.unsplash.com/photo-1533640934426-4080c4506793?auto=format&fit=crop&w=900&q=80', 65, 259.00, 'ON');
INSERT INTO `service_item` VALUES (32, 3, '通勤层次剪裁', '打造自然利落的通勤发型层次，兼顾精致度和日常易打理。', 'https://images.unsplash.com/photo-1560066984-138dadb4c035?auto=format&fit=crop&w=900&q=80', 70, 198.00, 'ON');
INSERT INTO `service_item` VALUES (33, 3, '法式空气刘海', '根据脸型修饰额头和脸部轮廓，打造轻盈柔和的刘海效果。', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=900&q=80', 50, 158.00, 'ON');
INSERT INTO `service_item` VALUES (34, 3, '男士纹理造型', '通过纹理修剪和轻造型提升头型比例，适合清爽自然风格。', 'https://images.unsplash.com/photo-1622286346003-cf0fdbda39c7?auto=format&fit=crop&w=900&q=80', 60, 188.00, 'ON');
INSERT INTO `service_item` VALUES (35, 3, '发尾柔顺护理', '改善发尾毛躁和干枯状态，让发丝更顺滑、有光泽。', 'https://images.unsplash.com/photo-1605497788044-5a32c7078486?auto=format&fit=crop&w=900&q=80', 75, 299.00, 'ON');
INSERT INTO `service_item` VALUES (36, 3, '冷棕护色染发', '选择低调耐看的冷棕色系，并同步关注染后发质护理。', 'https://images.unsplash.com/photo-1527799820374-dcf8d9d4a388?auto=format&fit=crop&w=900&q=80', 160, 659.00, 'ON');
INSERT INTO `service_item` VALUES (37, 3, '蓬松发根烫', '改善发根贴头皮状态，让整体发型更立体自然。', 'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=900&q=80', 120, 429.00, 'ON');
INSERT INTO `service_item` VALUES (38, 2, '午间快速舒压', '适合午休或碎片时间的快速放松项目，缓解肩颈和精神疲惫。', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=900&q=80', 35, 129.00, 'ON');
INSERT INTO `service_item` VALUES (39, 1, '奢宠面颈护理', '同时关注面部与颈部肌肤状态，适合重要场合前的精致护理。', 'https://images.unsplash.com/photo-1598970434795-0c54fe7c0642?auto=format&fit=crop&w=900&q=80', 100, 459.00, 'ON');
